-- Allow the new backend attachment audit event without rewriting previous migrations.
ALTER TABLE audit_records DROP CONSTRAINT ck_audit_records_action;
ALTER TABLE audit_records ADD CONSTRAINT ck_audit_records_action
    CHECK (action IN ('INCIDENT_CREATED', 'CLASSIFIED', 'PRIORITY_CALCULATED', 'PRIORITY_CHANGED', 'ASSIGNED', 'REASSIGNED', 'ACKNOWLEDGED', 'WORK_STARTED', 'INFO_REQUESTED', 'INFO_PROVIDED', 'RESOLVED', 'VERIFIED', 'CLOSED', 'REOPENED', 'ESCALATED', 'COMMENT_ADDED', 'SLA_WARNING', 'SLA_VIOLATED', 'DUPLICATE_LINKED', 'LOGIN_FAILED', 'ACCESS_DENIED', 'USER_ROLE_CHANGED', 'CONFIG_CHANGED', 'ATTACHMENT_ADDED'));
